import React from "react";

function InsightsPage({ transactions, alerts, insights, darkMode, goBack }) {

  // 🔹 CATEGORY TOTALS
  const getCategoryTotals = () => {
    let totals = {};

    transactions.forEach(t => {
      const cat = (t.category || "other").toLowerCase();
      totals[cat] = (totals[cat] || 0) + Number(t.amount || 0);
    });

    return totals;
  };

  const totals = getCategoryTotals();
  const totalSpend = Object.values(totals).reduce((a, b) => a + b, 0);

  return (
    <div className="card table-card">

      {/* 🔙 BACK BUTTON */}
      <div style={{ marginBottom: "16px" }}>
        <button
          onClick={goBack}
          style={{
            padding: "6px 12px",
            borderRadius: "8px",
            border: "1px solid #d1d5db",
            background: "transparent",
            cursor: "pointer"
          }}
        >
          ← Back to Dashboard
        </button>
      </div>

      <h2 style={{ marginBottom: "20px" }}>AI Financial Insights</h2>

      {/* 🧠 AI SUMMARY */}
      <div style={{ marginBottom: "20px" }}>
        {insights.map((i, idx) => (
          <p key={idx} style={{ marginBottom: "8px" }}>{i}</p>
        ))}
      </div>

      {/* 🥧 SPENDING DISTRIBUTION */}
      <h3 style={{ marginBottom: "10px" }}>Spending Distribution</h3>

      {Object.keys(totals).map((cat, i) => {
        const percent = ((totals[cat] / totalSpend) * 100).toFixed(1);

        return (
          <div key={i} style={{ marginBottom: "10px" }}>
            <div style={{
              display: "flex",
              justifyContent: "space-between",
              fontSize: "13px"
            }}>
              <span>{cat}</span>
              <span>{percent}%</span>
            </div>

            <div style={{
              height: "8px",
              background: darkMode ? "#374151" : "#e5e7eb",
              borderRadius: "6px",
              overflow: "hidden"
            }}>
              <div style={{
                width: `${percent}%`,
                height: "100%",
                background: "#4f6df5"
              }} />
            </div>
          </div>
        );
      })}

      {/* 📊 BUDGET VS SPENT */}
      <h3 style={{ marginTop: "20px", marginBottom: "10px" }}>
        Budget vs Spending
      </h3>

      {alerts.map((a, i) => {
        const percent = a.limit ? (a.spent / a.limit) * 100 : 0;

        return (
          <div key={i} style={{ marginBottom: "12px" }}>
            <div style={{
              display: "flex",
              justifyContent: "space-between",
              fontSize: "13px"
            }}>
              <span>{a.category}</span>
              <span>₹{a.spent} / ₹{a.limit}</span>
            </div>

            <div style={{
              height: "8px",
              background: darkMode ? "#374151" : "#e5e7eb",
              borderRadius: "6px",
              overflow: "hidden"
            }}>
              <div style={{
                width: `${Math.min(percent, 100)}%`,
                height: "100%",
                background: percent > 100 ? "#ef4444" : "#22c55e"
              }} />
            </div>
          </div>
        );
      })}

    </div>
  );
}

export default InsightsPage;
